from sympy import symbols,solve,Rational,simplify
x=symbols('x')
vals=[simplify(4*r/(r**2-5*r+8)) for r in solve(x**2+7*x+8,x)]
opts={'A':Rational(-1,3),'B':Rational(1,6),'C':Rational(1,2),'D':Rational(-1,4)}
assert all(simplify(v-opts['A'])==0 for v in vals)
for k in 'BCD': assert all(simplify(v-opts[k])!=0 for v in vals)

opts={'A':8,'B':12,'C':14,'D':6}
def ok(s):
    for t in (s,):
        sides=[6,12,t]
        iso=len(set(sides))<3
        tri=max(sides)<sum(sides)-max(sides)
        if not(iso and tri): return False
    return True
fit=[k for k,v in opts.items() if ok(v)]
assert fit==['B']
